-- GENERATED by `wfj generate` from data/gossip/gossip-8e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8e088a7391bc932f"] = { "Ci ha serviti tutti, anno dopo anno...", "." },
  ["8e0d60743656b109"] = { "Puoi anche avere la meglio sul campo di battaglia per un po'... ma non puoi sperare di vincere contro il Flagello!", "." },
  ["8e16f5a2fd90985e"] = { "Forse hai la stoffa giusta. Scopriamolo!", "." },
  ["8e174af782d2c650"] = { "Il maestro dei pipistrelli", "." },
  ["8e1b54dea59c512a"] = { "Ringo! Stai bene!", "." },
  ["8e2182bacbec37fe"] = { "Andiamo a giocare! No, raccontami una storia, papà! No... andiamo a raccogliere i fiori! E giochiamo al tè! Ho ritrovato la mia bambolina, te l'ho detto?", "." },
  ["8e24e14fddf22096"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ si trova sul lato sud del ⟦Field of Strife=Pian della Discordia⟧, a est della Torre di Brinarossa.\n\nAl momento è controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["8e312c3037781466"] = { "Ecco fatto: ora puoi costruire il tuo Rallying Banner personale. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa istruirti nelle arti culinarie per imparare le basi.", "." },
  ["8e39837b2c76f1b3"] = { "%s annusa l'esca.", "." },
  ["8e422b894921a820"] = { "Aye, tutti vogliono salire sul tram, è uno spasso. Beh, se vuoi trovare il tram, si trova a Tinker Town, appena a est dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["8e47a10fab32f00e"] = { "Vediamo come crescono questi semi nel terreno che ho preparato...", "." },
  ["8e4bdea5b90e0b5e"] = { "%s posa il carico di legna con un tonfo pesante.", "." },
  ["8e4be8248b5266ba"] = { "Tutte le risorse sono state raccolte. Evviva!", "." },
  ["8e4c2e46cae74249"] = { "%s fugge a rifugiarsi presso un'altra tigre.", "." },
  ["8e5705873bb46023"] = { "Dammi gli ordini! Li porterò a Teravaine nel ⟦Field of Strife=Pian della Discordia⟧!", "." },
  ["8e5d7327089e58d1"] = { "Non dovrei nemmeno dirtelo, ma se riesci a superare tutte le bestie e le bestiacce delle ⟦Badlands=Maleterre⟧, potresti riuscire ad arrivare alla ⟦Searing Gorge=Gorgia Rovente⟧.\n\nSì, le ⟦Badlands=Maleterre⟧. C'è una specie di strada secondaria che gli orchi hanno lastricato vicino a Kargath. Il che dimostra con che razza di idioti abbiamo a che fare! Una porta sul retro per l'inferno? Ma cosa avevano in testa?", "." },
  ["8e638bc1cc5fe8bf"] = { "Oh, Umi, ti prego, insegnami di nuovo a creare uno Yeti Pacifico. Mi manca tanto.", "." },
  ["8e66b78079444206"] = { "{name}! Sei <tornato/tornata> solo per parlare con me? Che pensiero gentile, e stai proprio una favola con quella tenuta!\n\nNon sai quanto mi fa piacere vederti. Quassù ci si può sentire piuttosto soli, visto che quasi tutti questi zoticoni non riescono nemmeno a vedermi. È stata una gran cosa quella che hai fatto per tutti noi, e non la dimenticherò mai!\n\nGrazie di essere <passato/passata> a salutare, e non sparire così.", "." },
  ["8e69d0d2973c11d7"] = { "AH, UN BANCHETTO! CHI L'HA LASCIATO QUI...?", "." },
  ["8e702f91bc040610"] = { "Affascinante. Ti prego, dimmi di più.", "." },
  ["8e715e4334dc44c5"] = { "Buona Festa del Grande Inverno dai tuoi amici della Masseria Buongusto!", "." },
  ["8e72216fe64479d4"] = { "Abbiamo quasi tutto il silithyst che ci serve! Per l'⟦Horde=Orda⟧!", "." },
  ["8e72c6908866d4f7"] = { "Non vedo in te lo spirito del guerriero, <figliolo/figliola>. Non ho insegnamenti che possano giovare a <un/una> {class} come te.", "." },
  ["8e74a5e4e8ca9612"] = { "%s scava per uscire dalla sabbia e proteggere le sue uova.", "." },
  ["8e76f50a35509568"] = { "Io... Be', forse ho preso una cosetta o due dalla locanda... ma a un ogre che gliene importa?", "." },
  ["8e7c2bc495c7d8ce"] = { "Fiu! È stato un bel lavoraccio, {race}. Non vedevo il Flagello così aggressivo da...\n\n<La guardia Didier deglutisce a fatica.>\n\nDall'ultima guerra...", "." },
  ["8e83a4cc164ae504"] = { "I segreti dietro il potere del Colosso potrebbero portare a ogni sorta di innovazione nella scienza!", "." },
  ["8ea08829e274e788"] = { "Sì, <fratello/sorella>, come posso aiutarti?", "." },
  ["8ea668b639b1a17e"] = { "Se avessi delle castagne, puoi scommetterci che le metterei ad arrostire sul fuoco. Mmmm!", "." },
  ["8ead5d54e91b78a2"] = { "Quella maghetta minuta, Bink, laggiù alla Hall of Mysteries, potrebbe probabilmente aiutarti per qualsiasi necessità magica.\n\nLa Hall of Mysteries è appena a nord dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["8ebf31106c5e854e"] = { "Ora vado a evocare il signore di questa dimora. Se cercherete udienza da lui, le vostre misere vite saranno senz'altro perdute! Ciononostante, cercate il suo covo, se ne avete il coraggio!", "." },
  ["8ec239bd8c9db3c7"] = { "Ok, andiamo!", "." },
  ["8ec42a5cdb543cd8"] = { "Proprio quello che mi serviva.", "." },
  ["8ed5c63aa68ef58c"] = { "Incredibile! Come osano??", "." },
  ["8edac29bb807de31"] = { "Questa è la prova che ti avevo chiesto. Hai fatto bene, {name}.\n\nSono felice di essere la prima a congratularmi con te e a darti questo... il tuo totem dell'acqua.\n\nUsalo bene, e buona fortuna.\n\nLa tua prossima prova non arriverà prima di un po' di tempo, quindi impara bene le tue lezioni. L'acqua pura non solo ridà la vita a chi è ferito, ma può avere molti altri effetti. Ti suggerisco di cercare un istruttore degli sciamani quando ne avrai il tempo. Potrebbe avere altri incantesimi da insegnarti.", "." },
  ["8edbbaa683592c76"] = { "Un'altra vittoria per la ⟦Defias Brotherhood=Fratellanza dei Defias⟧!", "." },
  ["8edbcf2658f2abae"] = { "%s esplode in una melma velenosa!", "." },
  ["8edc4baa5f61c427"] = { "Vek'nilash e Vek'lor, conosciuti come gli Imperatori Gemelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧, osservavano la guerra dal santuario del loro tempio. Gli astuti fratelli escogitarono un piano per demoralizzare e dividere le forze di Staghelm.", "." },
  ["8ee47ae68db6501f"] = { "Dov'è l'anziano Urlamazza?", "." },
  ["8ef887b9b9a49210"] = { "Sei qui per chiedere assistenza al censimento di ⟦Undercity=Sepulcra⟧, o solo per chiedermi se qualcuno che conoscevi è morto? Me lo chiedono spesso.", "." },
})
